238	+ * document it is (receipt, invoice, booking receipt) depends on how the guest is identified.
239	+ */
240	+public record ReservationDocument(
241	+        String title,
242	+        long reservationId,
243	+        String guestName,
244	+        String guestCpf,
245	+        String companyCnpj,
246	+        String companyName,
