275	+                reservation.price().subtotal(),
276	+                reservation.price().discount(),
277	+                reservation.price().total(),
278	+                null);
279	+        return draft.withText(layout.text(draft));
280	+    }
281	+
282	+    private ReservationDocument withText(String newText) {
283	+        return new ReservationDocument(
284	+                title, reservationId, guestName, guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
285	+                roomNumber, roomType, checkIn, checkOut, nights, subtotal, discount, total, newText);
